contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint a, uint b) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a) + (b)); require(a <= 1000000000000000000000000000000); require(b <= 1000000000000000000000000000000);
        require(a <= 10 ** 18);
        require(b <= 10 ** 18);
        require(address(this).balance >= a + b);

        c.addToBalance{value: a}(); if (__ESBMC_reverted()) return;
        c.addToBalance{value: b}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;

        c.withdrawBalance(); if (__ESBMC_reverted()) return;

        assert(
            balBefore == a + b
            && c.getBalance(address(this)) == 0
            && address(c).balance + (a + b) == ethBefore
        );
    }

    receive() external payable {}
}

